from taf.hw.vertex.devices.vertex import Vertex


class VertexVCE6(Vertex):
    """
    A hardware device class, provides basic methods to operate hardware.
    """
    _model = 'VCE6'

    def __init__(self, host=None, port=None, proxy=None, proxy_username=None, proxy_password=None, **kwargs):
        super(VertexVCE6, self).__init__(host, port, proxy, proxy_username, proxy_password, **kwargs)
